  static VALUES = { T: true, F: false, U: 'unknown' };

  static NOT(x) {
    return x === 'U' ? 'U' : !x;
  }

  static AND(x, y) {
    if (x === 'F' || y === 'F') return 'F';
    if (x === 'U' || y === 'U') return 'U';
    return 'T';
